//! Port of the comptime ORM half of `src/db/sqlite.zig` — WP-3.10.
//!
//! Zig generated the schema, the parameter binding and the row mapping from a
//! struct's fields at comptime (`sqlite.Table(T)`). In Rust that code is
//! generated by `#[derive(zant_macros::Table)]`, which implements the
//! [`TableModel`] trait below; [`Table`] is the `Table(T)` facade that runs the
//! generated SQL.
//!
//! The generated SQL text is byte-for-byte what `src/db/sqlite.zig` built, so
//! database files written by the Zig version open unchanged.

use std::marker::PhantomData;

use rusqlite::types::ValueRef;

use super::sqlite::{Database, DbError, SqliteResult, SqliteRow, Value};

/// An enum field stored as TEXT by its variant name (Zig `@tagName` /
/// `std.meta.stringToEnum`).
///
/// Zig derived this mapping from the enum declaration itself; Rust enums do not
/// expose their variant list to `#[derive(Table)]`, so the model implements this
/// trait next to the enum.
pub trait SqlEnum: Sized {
    /// The variant name written by `INSERT` / `UPDATE` (Zig `@tagName`).
    fn as_str(&self) -> &'static str;
    /// The variant with that name, if this app version still knows it.
    fn from_str(name: &str) -> Option<Self>;
    /// The first declared variant: Zig's fallback for a stored value this app
    /// version does not know (`defaultEnum`).
    const FIRST: Self;
}

/// Contract between `#[derive(Table)]` and [`Table`] (Zig's comptime
/// reflection over `T`).
///
/// The SQL constants are exactly the strings `src/db/sqlite.zig` generated from
/// the same model fields.
pub trait TableModel: Sized {
    /// Table name, quoted separately for SQL (`Zig table_name` / `@typeName`).
    const TABLE_NAME: &'static str;
    /// `TABLE_NAME` in double quotes, as it appears in the generated SQL.
    const TABLE_NAME_SQL: &'static str;
    /// Column names in struct field order.
    const COLUMNS: &'static [&'static str];
    /// `COLUMNS` as a quoted, comma separated SQL list (`"id", "name"`).
    const COLUMNS_SQL: &'static str;
    const CREATE_TABLE_SQL: &'static str;
    const SELECT_SQL: &'static str;
    const SELECT_BY_ID_SQL: &'static str;
    const INSERT_SQL: &'static str;
    const UPDATE_SQL: &'static str;
    const DELETE_SQL: &'static str;
    const DELETE_ALL_SQL: &'static str;
    const COUNT_SQL: &'static str;

    /// Column definition for `ALTER TABLE .. ADD COLUMN` when this field is
    /// missing from an older table file (Zig `addedColumn`). `None` for the
    /// auto-increment `id` column.
    fn added_column(index: usize) -> Option<String>;

    /// Parameters of [`Table::insert`] (every field but `id`).
    fn insert_params(value: &Self) -> Vec<Value>;

    /// Parameters of [`Table::update`] (every field but `id`, then `id`).
    fn update_params(value: &Self) -> Vec<Value>;

    /// Reads one model value from a result row (Zig `mapRow`).
    fn from_row(row: &SqliteRow<'_>) -> SqliteResult<Self>;
}

/// `Database::table::<T>()`: CRUD helpers for one model (Zig `Table(T)`).
pub struct Table<'a, T: TableModel> {
    db: &'a Database,
    model: PhantomData<T>,
}

impl<'a, T: TableModel> Table<'a, T> {
    pub(crate) fn new(db: &'a Database) -> Self {
        Table {
            db,
            model: PhantomData,
        }
    }

    pub fn name(&self) -> &'static str {
        T::TABLE_NAME
    }

    pub fn db(&self) -> &'a Database {
        self.db
    }

    /// Creates the table when it does not exist and adds columns that a newer
    /// model has but the file does not (Zig `create` + `addMissingColumns`).
    pub fn create(&self) -> Result<(), DbError> {
        self.db.exec(T::CREATE_TABLE_SQL)?;
        self.add_missing_columns()
    }

    fn add_missing_columns(&self) -> Result<(), DbError> {
        // Zig: `PRAGMA table_info(<quoted table name>)`, column name is #1.
        let info_sql = format!("PRAGMA table_info({})", T::TABLE_NAME_SQL);
        let mut present = vec![false; T::COLUMNS.len()];
        {
            let mut rows = self.db.query(&info_sql, ())?;
            while let Some(row) = rows.next()? {
                let column = row.text(1);
                for (index, name) in T::COLUMNS.iter().enumerate() {
                    if column == *name {
                        present[index] = true;
                    }
                }
            }
        }
        for (index, is_present) in present.iter().enumerate() {
            if *is_present {
                continue;
            }
            let Some(definition) = T::added_column(index) else {
                continue;
            };
            let alter = format!(
                "ALTER TABLE {} ADD COLUMN \"{}\" {}",
                T::TABLE_NAME_SQL,
                T::COLUMNS[index],
                definition
            );
            self.db.exec(&alter)?;
        }
        Ok(())
    }

    /// Inserts a row (every field but `id`) and returns the new row id.
    pub fn insert(&self, value: &T) -> Result<i64, DbError> {
        let mut stmt = self.db.prepare(T::INSERT_SQL)?;
        let params = T::insert_params(value);
        stmt.execute(rusqlite::params_from_iter(params))?;
        Ok(self.db.last_insert_id())
    }

    /// Reads one row by `id`; `None` when it does not exist.
    pub fn get(&self, id: i64) -> Result<Option<T>, DbError> {
        let mut stmt = self.db.prepare(T::SELECT_BY_ID_SQL)?;
        let mut rows = stmt.query([id]).map_err(DbError::BindFailed)?;
        match rows.next()? {
            Some(row) => Ok(Some(T::from_row(row)?)),
            None => Ok(None),
        }
    }

    /// Reads every row (Zig `all`).
    pub fn all(&self) -> Result<Vec<T>, DbError> {
        let mut stmt = self.db.prepare(T::SELECT_SQL)?;
        let mut rows = stmt.query([]).map_err(DbError::BindFailed)?;
        let mut list = Vec::new();
        while let Some(row) = rows.next()? {
            list.push(T::from_row(row)?);
        }
        Ok(list)
    }

    /// Number of rows (Zig `count`).
    pub fn count(&self) -> Result<i64, DbError> {
        let mut stmt = self.db.prepare(T::COUNT_SQL)?;
        let mut rows = stmt.query([]).map_err(DbError::BindFailed)?;
        if let Some(row) = rows.next()? {
            return Ok(row.get(0)?);
        }
        Ok(0)
    }

    /// Updates the row whose `id` matches `value` (Zig `update`).
    pub fn update(&self, value: &T) -> Result<(), DbError> {
        let mut stmt = self.db.prepare(T::UPDATE_SQL)?;
        let params = T::update_params(value);
        stmt.execute(rusqlite::params_from_iter(params))?;
        Ok(())
    }

    /// Deletes the row with `id` (Zig `delete`).
    pub fn delete(&self, id: i64) -> Result<(), DbError> {
        let mut stmt = self.db.prepare(T::DELETE_SQL)?;
        stmt.execute([id])?;
        Ok(())
    }

    /// Deletes every row (Zig `deleteAll`).
    pub fn delete_all(&self) -> Result<(), DbError> {
        self.db.exec(T::DELETE_ALL_SQL)
    }
}

/// One column of a result row as an owned [`Value`].
pub(super) fn row_value(row: &SqliteRow<'_>, index: usize) -> SqliteResult<Value> {
    Ok(match row.get_ref(index)? {
        ValueRef::Null => Value::Null,
        ValueRef::Integer(value) => Value::Integer(value),
        ValueRef::Real(value) => Value::Real(value),
        ValueRef::Text(bytes) => Value::Text(String::from_utf8_lossy(bytes).into_owned()),
        ValueRef::Blob(bytes) => Value::Blob(bytes.to_vec()),
    })
}

/// Column readers used by the generated `from_row`. They mirror Zig's
/// `row.int` / `row.float` / `row.isNull` coercion: a NULL column reads as
/// zero / empty, like `sqlite3_column_int64` and friends.
pub fn column_int<T>(row: &SqliteRow<'_>, index: usize) -> SqliteResult<T>
where
    T: TryFrom<i64>,
    <T as TryFrom<i64>>::Error: std::fmt::Debug,
{
    let value: i64 = row.get::<_, Option<i64>>(index)?.unwrap_or(0);
    Ok(T::try_from(value).expect("int cast"))
}

pub fn column_opt_int<T>(row: &SqliteRow<'_>, index: usize) -> SqliteResult<Option<T>>
where
    T: TryFrom<i64>,
    <T as TryFrom<i64>>::Error: std::fmt::Debug,
{
    match row.get::<_, Option<i64>>(index)? {
        Some(value) => Ok(Some(T::try_from(value).expect("int cast"))),
        None => Ok(None),
    }
}

pub fn column_float(row: &SqliteRow<'_>, index: usize) -> SqliteResult<f64> {
    Ok(row.get::<_, Option<f64>>(index)?.unwrap_or(0.0))
}

pub fn column_opt_float(row: &SqliteRow<'_>, index: usize) -> SqliteResult<Option<f64>> {
    row.get::<_, Option<f64>>(index)
}

pub fn column_bool(row: &SqliteRow<'_>, index: usize) -> SqliteResult<bool> {
    Ok(column_int::<i64>(row, index)? != 0)
}

pub fn column_opt_bool(row: &SqliteRow<'_>, index: usize) -> SqliteResult<Option<bool>> {
    Ok(column_opt_int::<i64>(row, index)?.map(|value| value != 0))
}

pub fn column_text(row: &SqliteRow<'_>, index: usize) -> SqliteResult<String> {
    Ok(row.get::<_, Option<String>>(index)?.unwrap_or_default())
}

pub fn column_opt_text(row: &SqliteRow<'_>, index: usize) -> SqliteResult<Option<String>> {
    row.get::<_, Option<String>>(index)
}

/// An enum column: unknown values are `None`, like Zig `std.meta.stringToEnum`.
pub fn column_enum<E: SqlEnum>(row: &SqliteRow<'_>, index: usize) -> SqliteResult<Option<E>> {
    Ok(column_opt_text(row, index)?.and_then(|name| E::from_str(&name)))
}
